        ];$required=['scope','authority','price','signature','consent','next_step'];
    }
    $keys=['open','context','facts','authority','objection','pressure','consent','close'];
    foreach($steps as $i=>$s){
        $a=[$s[1][0],$s[1][1],10,$s[1][2]];
        $b=[$s[2][0],$s[2][1],4];$c=[$s[3][0],$s[3][1],2];$d=[$s[4][0],$s[4][1],0,[],true];
        // Explicit refusals are facts even after a poor response; never hide them.
        if($id==='refusal'&&$i>=4){$b[3]=['consent'];$c[3]=['consent'];$d[3]=['consent'];$b[4]=true;$c[4]=true;}
        $add($keys[$i],$s[0],$keys[$i+1]??'crm',$a,$b,$c,$d);
